import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Quick Start — OpenShield-L7","description":"From zero to a protected, proxied site in 30 seconds — config.yaml, one sites.d file, gen-token, and the first API calls.","frontmatter":{"title":"Quick Start — OpenShield-L7","description":"From zero to a protected, proxied site in 30 seconds — config.yaml, one sites.d file, gen-token, and the first API calls."},"headers":[],"relativePath":"openshield-l7/getting-started/quick-start.md","filePath":"openshield-l7/getting-started/quick-start.md","lastUpdated":null}'),n={name:"openshield-l7/getting-started/quick-start.md"};function l(h,s,o,p,r,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>The 30-second path: one global config, one site file, one token, and a live request event. Assumes a <a href="./installation">built binary</a> (<code>cargo build --release</code>).</p><hr><h2 id="_1-create-the-project-root" tabindex="-1">1. Create the project root <a class="header-anchor" href="#_1-create-the-project-root" aria-label="Permalink to &quot;1. Create the project root&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myproxy/sites.d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myproxy</span></span></code></pre></div><h2 id="_2-config-yaml-—-global-config" tabindex="-1">2. <code>config.yaml</code> — global config <a class="header-anchor" href="#_2-config-yaml-—-global-config" aria-label="Permalink to &quot;2. \`config.yaml\` — global config&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:80&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listen_https</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:443&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:9090&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tokens</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bootstrap</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paste-a-long-random-string-here&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # &gt;= 16 chars</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span></span></code></pre></div><p>Generate a real token (prints the token plus a ready-to-paste YAML snippet):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span></span></code></pre></div><h2 id="_3-sites-d-example-yaml-—-one-site" tabindex="-1">3. <code>sites.d/example.yaml</code> — one site <a class="header-anchor" href="#_3-sites-d-example-yaml-—-one-site" aria-label="Permalink to &quot;3. \`sites.d/example.yaml\` — one site&quot;">​</a></h2><p>Point it at any web server you have running (here: <code>http://10.0.0.5:8080</code>):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostnames</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://10.0.0.5:8080&quot;</span></span></code></pre></div><p>That&#39;s a complete site. Everything else has working defaults: WAF on, per-IP 300 req/60s and per-site 5000 req/10s limits, <code>X-Forwarded-For</code> to the origin, no TLS, no quotas.</p><h2 id="_4-validate-then-run" tabindex="-1">4. Validate, then run <a class="header-anchor" href="#_4-validate-then-run" aria-label="Permalink to &quot;4. Validate, then run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # all configs valid (config.yaml + 1 site file(s) ...)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # needs root or CAP_NET_BIND_SERVICE for 80/443</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">First-run shortcut</p><p>If <code>config.yaml</code> is missing, <code>run</code> writes a documented default and generates one admin token, printed <strong>once</strong> to the console. You can skip steps 2–3 entirely and edit the generated files afterward.</p></div><h2 id="_5-push-a-request-through" tabindex="-1">5. Push a request through <a class="header-anchor" href="#_5-push-a-request-through" aria-label="Permalink to &quot;5. Push a request through&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%{http_code}\\n&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Host: example.com&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 200</span></span></code></pre></div><h2 id="_6-talk-to-the-admin-api" tabindex="-1">6. Talk to the admin API <a class="header-anchor" href="#_6-talk-to-the-admin-api" aria-label="Permalink to &quot;6. Talk to the admin API&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paste-a-long-random-string-here&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/health</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;status&quot;:&quot;ok&quot;}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/stats/global</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;uptime_secs&quot;:61,&quot;version&quot;:&quot;0.1.0&quot;,&quot;sites_total&quot;:1,&quot;sites_enabled&quot;:1,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  &quot;total_requests&quot;:3,&quot;blocked&quot;:0,&quot;challenged&quot;:0,&quot;bytes_up&quot;:936,&quot;bytes_down&quot;:10420,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#  &quot;active_connections&quot;:0,&quot;rps_1m&quot;:0.05}</span></span></code></pre></div><h2 id="_7-watch-a-request-event-live" tabindex="-1">7. Watch a request event live <a class="header-anchor" href="#_7-watch-a-request-event-live" aria-label="Permalink to &quot;7. Watch a request event live&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/api/v1/events/stream</span></span></code></pre></div><p>In another shell, repeat the <code>curl</code> from step 5 — a frame appears within a second:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;kind&quot;:&quot;request&quot;,&quot;ts_ms&quot;:1723000000123,&quot;site&quot;:&quot;example-com&quot;,&quot;client_ip&quot;:&quot;127.0.0.1&quot;,&quot;peer_ip&quot;:&quot;127.0.0.1&quot;,&quot;method&quot;:&quot;GET&quot;,&quot;host&quot;:&quot;example.com&quot;,&quot;path&quot;:&quot;/&quot;,&quot;status&quot;:200,&quot;action&quot;:&quot;allowed&quot;,&quot;rule_hits&quot;:[],&quot;latency_us&quot;:1843,&quot;bytes_up&quot;:312,&quot;bytes_down&quot;:10420,&quot;user_agent&quot;:&quot;curl/8.5.0&quot;,&quot;referer&quot;:&quot;&quot;,&quot;conn_bumped_ip&quot;:false,&quot;conn_bumped_site&quot;:false}</span></span></code></pre></div><h2 id="_8-feel-the-hot-reload" tabindex="-1">8. Feel the hot reload <a class="header-anchor" href="#_8-feel-the-hot-reload" aria-label="Permalink to &quot;8. Feel the hot reload&quot;">​</a></h2><p>Edit <code>sites.d/example.yaml</code> while it runs — changes hot-apply within a second. Break the YAML on purpose: the site keeps running on its last good config and a <code>config_reload</code> event on the stream reports the failure. Details: <a href="./../user-guide/hot-reload">Hot Reload</a>.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — TLS, rate limits, WAF rules, challenges, quotas.</li><li><strong><a href="./../user-guide/api">Admin API →</a></strong> — Create sites, ban IPs, pull analytics without touching files.</li><li><strong><a href="./../architecture/transparent-ip">Transparent Client IP →</a></strong> — Make the origin see the real client IP with zero origin config.</li></ul>`,29)])])}const c=a(n,[["render",l]]);export{u as __pageData,c as default};
